423  static espeak_ng_STATUS Synthesize(unsigned int unique_identifier, const void *text, int flags)
   424  {
   425          // Fill the buffer with output sound
   426          int length;
   427          int finished = 0;
   428          int count_buffers = 0;
   429
   430          if ((outbuf == NULL) || (event_list == NULL))
   431                  return ENS_NOT_INITIALIZED;
   432
   433          option_ssml = flags & espeakSSML;
   434          option_phoneme_input = flags & espeakPHONEMES;
   435          option_endpause = flags & espeakENDPAUSE;
   436
   437          count_samples = 0;
   438
   439          espeak_ng_STATUS status;
   440          if (translator == NULL) {
   441                  status = espeak_ng_SetVoiceByName("en");
   442                  if (status != ENS_OK)
   443                          return status;
   444          }
   445
   446          if (p_decoder == NULL)
   447                  p_decoder = create_text_decoder();
   448
   449          status = text_decoder_decode_string_multibyte(p_decoder, text, translator->encoding, flags);
   450          if (status != ENS_OK)
   451                  return status;
   452
   453          SpeakNextClause(0);
   454
   455          for (;;) {
   456                  out_ptr = outbuf;
   457                  out_end = &outbuf[outbuf_size];
   458                  event_list_ix = 0;
   459                  WavegenFill();
   460
   461                  length = (out_ptr - outbuf)/2;
   462                  count_samples += length;
   463                  event_list[event_list_ix].type = espeakEVENT_LIST_TERMINATED; // indicates end of event list
   464                  event_list[event_list_ix].unique_identifier = unique_identifier;
   465                  event_list[event_list_ix].user_data = my_user_data;
   466
   467                  count_buffers++;
   468                  if ((my_mode & ENOUTPUT_MODE_SPEAK_AUDIO) == ENOUTPUT_MODE_SPEAK_AUDIO) {
   469                          finished = create_events((short *)outbuf, length, event_list);
   470                          if (finished < 0)
   471                                  return ENS_AUDIO_ERROR;
   472                  } else if (synth_callback)
   473                          finished = synth_callback((short *)outbuf, length, event_list);
   474                  if (finished) {
   475                          SpeakNextClause(2); // stop
   476                          return ENS_SPEECH_STOPPED;
   477                  }
   478
   479                  if (Generate(phoneme_list, &n_phoneme_list, 1) == 0) {
   480                          if (WcmdqUsed() == 0) {
   481                                  // don't process the next clause until the previous clause has finished generating speech.
   482                                  // This ensures that <audio> tag (which causes end-of-clause) is at a sound buffer boundary
   483
   484                                  event_list[0].type = espeakEVENT_LIST_TERMINATED;
   485                                  event_list[0].unique_identifier = my_unique_identifier;
   486                                  event_list[0].user_data = my_user_data;
   487
   488                                  if (SpeakNextClause(1) == 0) {
   489                                          finished = 0;
   490                                          if ((my_mode & ENOUTPUT_MODE_SPEAK_AUDIO) == ENOUTPUT_MODE_SPEAK_AUDIO) {
   491                                                  if (dispatch_audio(NULL, 0, NULL) < 0)
   492                                                          return ENS_AUDIO_ERROR;
   493                                          } else if (synth_callback)
   494                                                  finished = synth_callback(NULL, 0, event_list); // NULL buffer ptr indicates end of data
   495                                          if (finished) {
   496                                                  SpeakNextClause(2); // stop
   497                                                  return ENS_SPEECH_STOPPED;
   498                                          }
   499                                          return ENS_OK;
   500                                  }
   501                          }
   502                  }
   503          }
   504  }
